import{_ as t,c as a,o,ae as s}from"./chunks/framework.CliRSA9F.js";const r="/images/command_center.webp",m=JSON.parse('{"title":"Command Center","description":"","frontmatter":{},"headers":[],"relativePath":"features/command-center.md","filePath":"features/command-center.md"}'),n={name:"features/command-center.md"};function i(h,e,l,d,c,g){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="command-center" tabindex="-1">Command Center <a class="header-anchor" href="#command-center" aria-label="Permalink to &quot;Command Center&quot;">​</a></h1><h2 id="your-podcast-s-home-base" tabindex="-1">Your Podcast&#39;s Home Base <a class="header-anchor" href="#your-podcast-s-home-base" aria-label="Permalink to &quot;Your Podcast&#39;s Home Base&quot;">​</a></h2><p>The Command Center is your starting point in PodSEO. It brings together the most important signals about your podcast&#39;s health, surfaces what needs attention, and tells you what to do next — all in one view.</p><p><img src="'+r+'" alt="Command Center Dashboard" width="600px" style="display:block;margin:0 auto;"></p><p><strong>To access</strong>: Click <strong>Command Center</strong> in the sidebar.</p><h2 id="what-you-ll-see" tabindex="-1"><strong>What You&#39;ll See</strong> <a class="header-anchor" href="#what-you-ll-see" aria-label="Permalink to &quot;**What You&#39;ll See**&quot;">​</a></h2><h3 id="status-line" tabindex="-1"><strong>Status Line</strong> <a class="header-anchor" href="#status-line" aria-label="Permalink to &quot;**Status Line**&quot;">​</a></h3><p>At the top, a daily status message summarizes where things stand. If areas need attention, they&#39;re called out directly. This status adapts based on how recently you&#39;ve visited — if you&#39;ve been away, it highlights what changed while you were gone.</p><h3 id="get-started-new-users" tabindex="-1"><strong>Get Started (New Users)</strong> <a class="header-anchor" href="#get-started-new-users" aria-label="Permalink to &quot;**Get Started (New Users)**&quot;">​</a></h3><p>When you first add a podcast, the Command Center shows a guided setup flow with numbered steps to help you:</p><ol><li><strong>Choose keywords</strong> — Set your primary keywords so you can track how your podcast ranks in search (once set, this becomes &quot;Review keywords&quot; to confirm they match your strategy)</li><li><strong>Add a competitor</strong> — Add at least one competitor to see how you compare (once added, this becomes &quot;Review competitors&quot; to confirm they&#39;re relevant)</li><li><strong>Check your platforms</strong> — Make sure your show is available across the platforms where listeners discover podcasts</li></ol><p>These steps disappear once you&#39;ve completed the initial setup.</p><h3 id="health-signals" tabindex="-1"><strong>Health Signals</strong> <a class="header-anchor" href="#health-signals" aria-label="Permalink to &quot;**Health Signals**&quot;">​</a></h3><p>Signal cards give you a quick read on key areas of your podcast&#39;s performance:</p><ul><li><strong>Visibility Score</strong> — Your overall discoverability metric across platforms, shown as a prominent anchor card</li><li><strong>Content health</strong> — Whether your publishing cadence and metadata are on track</li><li><strong>Keyword performance</strong> — How your tracked keywords are ranking</li><li><strong>Promotion signals</strong> — Editorial features, chart appearances, and other growth indicators</li></ul><p>Each signal shows its current value, a status indicator (healthy, needs attention, or critical), and a direct link to take action.</p><h3 id="what-s-changing-insights" tabindex="-1"><strong>What&#39;s Changing (Insights)</strong> <a class="header-anchor" href="#what-s-changing-insights" aria-label="Permalink to &quot;**What&#39;s Changing (Insights)**&quot;">​</a></h3><p>The insights section surfaces notable movements and opportunities:</p><ul><li><strong>Competitor weakness</strong> — When a competitor loses a ranking, creating an opportunity for you to move up</li><li><strong>Rank breakthrough</strong> — When you&#39;re close to breaking into the top 10 for a keyword</li><li><strong>Falling keyword</strong> — When one of your rankings is slipping and needs attention</li><li><strong>Stale metadata</strong> — When your podcast information hasn&#39;t been updated in a while</li></ul><p>Each insight links directly to where you can take action.</p><h3 id="what-to-do-next-tasks" tabindex="-1"><strong>What to Do Next (Tasks)</strong> <a class="header-anchor" href="#what-to-do-next-tasks" aria-label="Permalink to &quot;**What to Do Next (Tasks)**&quot;">​</a></h3><p>A prioritized list of actions based on your podcast&#39;s current state and your optimization cadence. Tasks are generated from across PodSEO — keyword strategy reviews, metadata updates, competitor checks, and more.</p><p>Priority tasks are highlighted, and overdue items show how many days have passed since they were due. Each task links to the relevant feature so you can act immediately.</p><h2 id="sub-pages" tabindex="-1"><strong>Sub-Pages</strong> <a class="header-anchor" href="#sub-pages" aria-label="Permalink to &quot;**Sub-Pages**&quot;">​</a></h2><p>The Command Center is also the gateway to three important features:</p><ul><li><strong><a href="/features/planner.html">Planner</a></strong> — Plan episodes, check metadata alignment, and get AI-powered content suggestions</li><li><strong><a href="/features/positioning.html">Positioning</a></strong> — Define your podcast&#39;s long-term strategic positioning</li><li><strong><a href="/features/pulse.html">Pulse</a></strong> — Discover trending topics relevant to your podcast&#39;s niche</li></ul><h2 id="strategic-use" tabindex="-1"><strong>Strategic Use</strong> <a class="header-anchor" href="#strategic-use" aria-label="Permalink to &quot;**Strategic Use**&quot;">​</a></h2><h3 id="daily-check-in" tabindex="-1"><strong>Daily Check-In</strong> <a class="header-anchor" href="#daily-check-in" aria-label="Permalink to &quot;**Daily Check-In**&quot;">​</a></h3><p>Make the Command Center your first stop when you open PodSEO. The status line and signals tell you immediately whether anything needs attention, saving you from checking each section individually.</p><h3 id="weekly-review" tabindex="-1"><strong>Weekly Review</strong> <a class="header-anchor" href="#weekly-review" aria-label="Permalink to &quot;**Weekly Review**&quot;">​</a></h3><p>Use the insights and tasks sections for your weekly optimization review. The Command Center aggregates signals from across PodSEO so you can prioritize your time effectively.</p><h3 id="after-changes" tabindex="-1"><strong>After Changes</strong> <a class="header-anchor" href="#after-changes" aria-label="Permalink to &quot;**After Changes**&quot;">​</a></h3><p>After updating metadata, publishing episodes, or changing your keyword strategy, check back to see how signals respond. The Command Center reflects changes as PodSEO processes new data.</p><h2 id="integration-with-other-features" tabindex="-1"><strong>Integration with Other Features</strong> <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;**Integration with Other Features**&quot;">​</a></h2><p>The Command Center connects to every part of PodSEO:</p><ul><li>Signal cards link to <strong><a href="/features/visibility-progress.html">Visibility Progress</a></strong>, <strong><a href="/features/keyword-strategy.html">Keyword Strategy</a></strong>, and <strong><a href="/features/my-placements.html">Editorial Presence</a></strong></li><li>Tasks guide you to <strong><a href="/features/planner.html">Planner</a></strong>, <strong><a href="/features/competitive-analysis.html">Competitive Analysis</a></strong>, and other features</li><li>Insights connect to <strong><a href="/features/show-rankings.html">Show Rankings</a></strong> and <strong><a href="/features/keyword-tracker.html">Keyword Tracker</a></strong> for deeper analysis</li></ul><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Start every PodSEO session at the Command Center to quickly assess what needs your attention</li><li>Don&#39;t ignore &quot;needs attention&quot; signals — they indicate areas where your podcast&#39;s discoverability could be declining</li><li>Use the task list to stay on a regular optimization cadence rather than making changes sporadically</li><li>The insights section is especially valuable after time away — it catches you up on what changed</li></ul><p>The Command Center transforms podcast optimization from a scattered process into a focused, prioritized workflow. Let it guide your efforts toward the actions that matter most.</p>',40)])])}const p=t(n,[["render",i]]);export{m as __pageData,p as default};
